import{_ as d,b as a,c as e,I as r}from"./chunks/framework.C6cPs9Ia.js";const h=JSON.parse('{"title":"通学路歌单：七点二十分的电车上","description":"一个高中生的通学歌单分享，附每首歌的一段小小感受","frontmatter":{"title":"通学路歌单：七点二十分的电车上","date":"2026-07-22T00:00:00.000Z","tags":["音乐","日常"],"cover":"/LQY/wallpaper-878514.webp","head":[["meta",{"name":"description","content":"一个高中生的通学歌单分享，附每首歌的一段小小感受"}],["meta",{"name":"keywords","content":"歌单, 通学路, J-POP, 音乐分享"}]]},"headers":[],"relativePath":"posts/commute-playlist.md","filePath":"posts/commute-playlist.md"}'),o={name:"posts/commute-playlist.md"};function s(l,t,n,i,p,c){return a(),e("div",null,[...t[0]||(t[0]=[r('<p>从家门口到校门口，电车 + 步行一共 23 分钟。这 23 分钟是我一天里唯一完全属于自己的时间，配什么歌很重要。分享本学期常驻歌单。</p><hr><h2 id="歌单本体" tabindex="-1">歌单本体 <a class="header-anchor" href="#歌单本体" aria-label="Permalink to &quot;歌单本体&quot;">​</a></h2><p>顺序是刻意排的，从出门到进校门，情绪曲线如下：</p><table tabindex="0"><thead><tr><th>#</th><th>曲目</th><th>阶段</th><th>备注</th></tr></thead><tbody><tr><td>1</td><td>Unmei ♀ (天下第一武士道 Ver.)</td><td>出门</td><td>BGM 一响，步伐自动加快</td></tr><tr><td>2</td><td>秒速 5 センチメートル</td><td>上车前</td><td>电车进站时的专属 BGM</td></tr><tr><td>3</td><td>アイドル</td><td>高架段</td><td>副歌正好赶上看日出那一段</td></tr><tr><td>4</td><td>ヨワネハキ</td><td>平稳段</td><td>闹钟没睡醒时专用，防止睡着坐过站</td></tr><tr><td>5</td><td>神っぽいな</td><td>换乘段</td><td>步行换乘的节奏适配曲</td></tr><tr><td>6</td><td>学園天国</td><td>最后一公里</td><td>校门在望，士气 MAX</td></tr><tr><td>7</td><td>蔚蓝档案 OST: Constant Moderato</td><td>到校</td><td>进教室前的平复心情曲</td></tr></tbody></table><h2 id="几首想说两句的" tabindex="-1">几首想说两句的 <a class="header-anchor" href="#几首想说两句的" aria-label="Permalink to &quot;几首想说两句的&quot;">​</a></h2><p><strong>《Constant Moderato》</strong></p><p>游戏基沃托斯的日常曲。前奏一响，教室、走廊、自动贩卖机的画面自动浮现。把它排在歌单最后是有私心的——提醒自己上学的日常本身，也是值得配 BGM 的故事。</p><p><strong>《アイドル》</strong></p><p>去年现象级的歌，现在听还是起劲。有一回副歌部分跟着哼出了声，前座的同学默默递来一张纸条：「耳机漏音」。社死实录，但没换歌。</p><p><strong>《秒速 5 センチメートル》</strong></p><p>新海诚的曲子有个特点：和&quot;电车&quot;这个场景天然适配。窗外风景掠过的速度感和弦乐的推进完美同步，谁试谁知道。</p><h2 id="关于耳机" tabindex="-1">关于耳机 <a class="header-anchor" href="#关于耳机" aria-label="Permalink to &quot;关于耳机&quot;">​</a></h2><div class="info custom-block"><p class="custom-block-title">装备与安全</p><ul><li>设备：一条百元级的有线塞，防止电车上被&quot;借走&quot;</li><li>音量：<strong>永远不超过 60%</strong>——过路口和站台广播必须听得见，这不是建议是纪律</li><li>备用歌单：「自习室白噪音」合集，晚自习回来路上切换</li></ul></div><details><summary>为什么不全用降噪耳机？</summary><p>试过一次，世界安静得可怕，坐过了两站。 通学路需要保留一部分对现实的感知力——比如身后有人喊你的名字，比如书包拉链开了。降噪留给写作业和睡觉。</p></details><p>歌单就分享到这里。如果你也有通学路的固定曲目，欢迎评论交流——毕竟 23 分钟的 BGM，值得反复打磨。</p>',16)])])}const u=d(o,[["render",s]]);export{h as __pageData,u as default};
